```latex
\section{Preliminaries}\label{sec:prelim}
\paragraph{Problem Setup and Notation.}
Throughout most of the paper, we will focus on a linear system $\A\x = \b$ where $\A \in \R^{m \times n}$ and $\b \in \R^m$. Let $\rank(\A) = r$ and $\{\sigma_i\}_{i=1}^r$ be the decreasing singular values of $\A$.  

For vector $\v$, we use $\|\v\|$ to denote its Euclidean norm, and for a psd matrix $\M$, we denote $\|\v\|_\M := \sqrt{\v^\top\M\v}$. For matrix $\A$, we denote $\|\A\|_2$ and $\|\A\|_F$ as its operator norm and Frobenius norm respectively. 

For $1 \leq \tau \leq m$, we use $\tbinom{[m]}{\tau}$ to denote the set of all the $\tau$-element subsets of $[m] = \{1, 2, \ldots, m\}$. For each $S\in\tbinom{[m]}{\tau}$, we use $\I_S\in\R^{\tau \times m}$ to denote the matrix obtained from $m\times m$ identity matrix $\I$ by only retaining the rows whose indices are in $S$. For matrix $\L \in \R^{m \times m}$ and subset $S\in\tbinom{[m]}{\tau}$, we use $\L_{S, S} = \I_S\L\I_S^\top  \in \R^{\tau \times \tau}$ to denote the principal submatrix located at the intersection of the rows and columns with indices from $S$, we also denote $\L_{:,S} = \L\I_S^\top$ and $\L_{S,:} = \I_S \L$ respectively.

\paragraph{Determinantal point processes.}
Given a PSD matrix with dimension $m$, a determinantal point process ($\dpp$) is a probability measure defined over $2^{[m]}$, i.e., all the subsets of $[m]$. There is a special class of $\dpp$s where we restrict the size of the subsets to be fixed, we call this a fixed-size $\dpp$ or $k$-DPP, where $k$ is the size of the subsets. Formally we have the following definitions.
\begin{definition}[$k$-DPP]
Given a PSD matrix $\L\in\R^{m \times m}$, a $k$-$\dpp$ is a distribution on $\tbinom{[m]}{k}$ such that $\Pr\{S\} \propto \det(\L_{S,S})$ where $S$ satisfies $|S| = k$. We denote it as $k$-$\dpp(\L)$.
\end{definition}
\begin{definition}[Projection DPP]
Given a PSD matrix $\L\in\R^{m \times m}$, a $k$-$\dpp$ is called a Projection $\dpp$ iff $k = \rank(\L)$. We denote it as $\mathrm{P}$-$\dpp(\L)$.
\end{definition}
\begin{lemma}[Algorithm 8 and Theorem 5.2 in \cite{kt12}]\label{lem:sample_dpp_projection}
Given $\L \in \R^{m \times m}$ with $\rank(\L) = r$, let $\L = \sum_i \lambda_i \u_i\u_i^\top$ be the eigendecomposition of $\L$ where $\lambda_1\geq \cdots\geq \lambda_m$. Suppose that we sample $\gamma = (\gamma_1, \ldots, \gamma_r)$ where $\gamma_i\sim\mathrm{Bernoulli}(\frac{\lambda_i}{\lambda_i+1})$ are independent, and then sample $S \sim \mathrm{P}$-$\dpp(\sum_i \gamma_i \u_i\u_i^\top)$. Then, conditioned on the event that $\sum_{i} \gamma_i = k$, we have $S \overset{d}{=} S_{\dpp}$, where $S_{\dpp} \sim k$-$\dpp(\L)$.
\end{lemma}

\paragraph{Total variation distance.}
\begin{definition}[Total variation distance]
Let $\mu, \nu$ be probability measures defined on a measurable space $(\Omega, \mathcal{F})$, the total variation distance between $\mu$ and $\nu$ is defined as
\begin{align*}
\delta(\mu, \nu) = \sup_{A\in\mathcal{F}} |\mu(A) - \nu(A)|.
\end{align*}
\end{definition}

\begin{definition}[Coupling, see Definition 4.12 in \cite{v14}]
Let $\mu, \nu$ be two probability measures defined on $\Omega_1, \Omega_2$ respectively. We say a joint distribution of random variable $Z = (X,Y)$ over $\Omega_1 \times \Omega_2$ is a coupling of $\mu$ and $\nu$, if it has marginal distributions $X\sim \mu$ and $Y\sim \nu$.
\end{definition}

\begin{lemma}[Total variation, see Example 4.14 in \cite{v14}]
\label{lem:tv_distance}
Let $\mu, \nu$ be probability measures defined on some $(\Omega,\mathcal F)$. Then, we have
$\inf_{(X,Y)}\Pr\{X\neq Y\} = \delta(\mu, \nu)$,
where the infimum is taken over all couplings of $\mu$ and $\nu$.
\end{lemma}

\paragraph{Randomized Hadamard transform.} 
\begin{definition} \label{hada} The Hadamard matrix $\H_{2^k}$ of dimension $2^k \times 2^k$ is obtained using the following recurrence relation
\begin{align*}
    \H_0 &= [1],\qquad
    \H_{2n} = \begin{bmatrix}
        \H_n & \H_n \\
        \H_n & -\H_n
    \end{bmatrix}.
\end{align*}
\end{definition}
\noindent
Throughout the paper, we will drop the subscript from $\H$, when the dimensions are clear.
\begin{definition} \label{def:RHT}
The randomized Hadamard transform (RHT) of an $m \times n$ matrix $\A$ is the product $\frac{1}{\sqrt{m}}\H\D\A$, where $\D$ is a random $m \times m$ diagonal matrix whose entries are independent random $\pm1$ signs. By padding $\A$ with zero rows if necessary, we may assume that $n$ is a power of~2. 
\end{definition}

\begin{lemma}[Rademacher tail bound, e.g., \cite{t11}]\label{lem:rademacher}
Let $f$ be a convex function on vectors with Lipschitz bound $|f(\x) - f(\y)| \leq L \|\x-\y\|$. Let $\mathbf{d}$ be a Rademacher vector. Then, for all $t \geq 0$,
\begin{align*}
\Pr\left\{f(\mathbf{d}) \geq \E[f(\mathbf{d})] + Lt\right\} \leq e^{-t^2/8}.
\end{align*}
\end{lemma}

\section{Replacing DPP with Uniform Sampling}\label{sec:sampling}
\begin{lemma}[Theorem 3 in \cite{alv22}]
\label{lem:anari_main_2}
Given a strongly Rayleigh distribution $\mu \in \R^{\tbinom{[m]}{k}}$ and marginal overestimates $q_i \geq \Pr_{T\sim\mu}\{i\in T\}$ for $i\in[m]$. Let $K := \sum_{i\in [m]} q_i$, there is an algorithm that outputs a sample from a distribution with total variation distance $m^{-O(1)}$ from $\mu$ in time bounded by $O(\log^3 m)$ calls to $\mathcal{T}_\mu(O(K), k)$, where $\mathcal{T}_\mu(t, k)$ is the time it takes to produce a sample from $\mu$ conditioned on all elements of the sample being a subset of a fixed set $T$ of size $|T| = t$. 
\end{lemma}

\begin{algorithm}[!ht]
\caption{$k$-DPP sampling algorithm based on \cite{alv22} (Ghost Algorithm).}
\label{alg:dpp_sample_ghost}
\begin{algorithmic}[1]
\State \textbf{Input: }$m, k, t, \mathrm{iter}, \mathrm{call}, \mathcal{O}$;
\State \textbf{Initialize }$S_0 \in  \tbinom{[m]}{k}, T_0 \gets \varnothing$; \Comment{By calling $\tilde{O}(k)$ times the oracle.}
\For{$i = 0, 1, 2, \ldots, \mathrm{iter}-1$} \Comment{$\mathrm{iter} = O(\log^3 m)$.}
\State \textbf{Initialize }$T_{i, 0} \gets T_i$;
\For{$j = 0, 1, 2, \ldots, \mathrm{call}-1$} \Comment{$\mathrm{call} \geq Ck$ for some $C=O(1)$.}
\State Sample $i_j$ by calling $ \mathcal{O}$;
\If{$i_j \in S_i \cup T_{i,j}$}:
\State $T_{i, j+1} = T_{i, j}$;
\Else: 
\State $T_{i, j+1} = T_{i,j} \cup \{i_j\}$;
\EndIf
\EndFor
\State \textbf{Update }$T_{i+1} \gets T_{i, \mathrm{call}}$; \Comment{Up-walk step by calling $ \tilde{O}(t-k)$ times the oracle.}
\State \textbf{Update }$S_{i+1} \subseteq S_i \cup T_{i+1}$; \Comment{Down-walk sampling from a $k$-DPP restricted to $S_i \cup T_{i+1}$.}
\EndFor \\
\Return $S_{\mathrm{iter}}$.
\end{algorithmic}
\end{algorithm}

In this whole section, we denote $\mathbf{Q} = \frac{1}{\sqrt{m}} \H \mathbf{D}$ as the RHT matrix, where $\H \in\R^{m \times m}$ is the Hadamard matrix and $\mathbf{D} \in \R^{m\times m}$ is the diagonal matrix with Rademacher entries. We denote $\bar{\A} = \Q\A$ as the preprocessed matrix.

\begin{remark}\label{rem:approx_iso}
Since we assume that $k \geq \log m$, by setting $\delta = 0.01$ we have
\begin{align*}
\Pr\{j \in S_{\dpp}\} \leq  \left(\sqrt{\frac{k}{m}} + \sqrt{\frac{8\log(m / \delta)}{m}}\right)^2 \leq \frac{2k}{m}+ \frac{16\log(m / \delta)}{m} \leq \frac{c_0 k}{m}
\end{align*}
for some constant $c_0=O(1)$. This shows that after the randomized Hadamard transform, the marginals are approximately isotropic up to a constant factor with probability $0.99$.
\end{remark}
```


