We start by proving the following 2 auxiliary statements:

\begin{lemma}\label{lem:sample_log}
Suppose we have an oracle that can uniformly sample one element from $[m]$. Suppose we have $S \in \tbinom{[m]}{k}$ where $k \leq m$. Let $t = O(k)$ and $0 < \delta < 1$, then with probability $1 - \delta$, after at most $O(t+\log\frac{1}{\delta})$ calls to the oracle, we can obtain $T := \cup_{j=1}^t \{i_j\}$ such that $T \subseteq [m] \backslash S$.
\end{lemma}
\begin{proof}[Proof of Lemma~\ref{lem:sample_log}]
We first state Lemma~\ref{lem:geo_tail} which is the tail bounds for sums of geometric random variables.
\begin{lemma}[Theorem 2.1 in \cite{j18}]\label{lem:geo_tail}
Let $\{X_i\}_{i=1}^n$ be independent geometric random variables with possibly different distributions: $X_i \sim p_i$ where $0 < p_i \leq 1$. Let $X := \sum_{i=1}^n X_i, \mu := \E[X]$ and $p_* := \min_i p_i$. For any $\lambda \geq 1$, we have
\begin{align*}
\Pr\{X \geq \lambda \mu\} \leq e^{-p_*\mu(\lambda-1-\ln\lambda)}.
\end{align*}
\end{lemma}
For $i\in[t]$, we define random variable $X_i$ as the number of calls it take to obtain a new sample in the $i$-th step (that is, we have obtained $i-1$ samples and want to get the $i$-th new sample). Then we know that $\{X_i\}_{i=1}^t$ are  independent geometric random variables with different distributions: $X_i \sim \mathrm{Ge}(p_i)$ where $p_i = 1- \frac{k+i-1}{m}$. We denote $X := \sum_{i=1}^t X_i$ and also define
\begin{align*}
\begin{cases}
\mu :=  \E[X] = \sum_{i=1}^t \E[X_i] = \sum_{i=1}^t \frac{1}{p_i} \\
p_* := \min_i p_i = 1 - \frac{k+t-1}{m}
\end{cases}
\end{align*}
Then we have
\begin{align*}
\mu = & ~ \frac{m}{m-k} + \frac{m}{m-k-1} + \cdots + \frac{m}{m - k - t +1} \\
= & ~ \frac{1}{1 - \frac{k}{m}} + \frac{1}{1 - \frac{k+1}{m}} + \cdots + \frac{1}{1 - \frac{k+t-1}{m}} \\
\leq & ~ (1 + \frac{2k}{m}) + (1 + \frac{2(k+1)}{m}) + \cdots + (1 + \frac{2(k+t-1)}{m}) \\
= & ~ t + \frac{2kt + t(t-1)}{m} \\
= & ~ t \cdot \left(1+\frac{2k+t-1}{m}\right)
\end{align*}
where the third step follows from $k, t \ll m$. Next we lower bound $p_* \mu$:
\begin{align*}
p_* \mu = & ~ \left(1 - \frac{k+t-1}{m}\right)\left(\frac{1}{1 - \frac{k}{m}} + \frac{1}{1 - \frac{k+1}{m}} + \cdots + \frac{1}{1 - \frac{k+t-1}{m}}\right) \\
= & ~ t - \sum_{i=1}^t \frac{t- i}{m-(k+i-1)} \\
\geq & ~ t - t\cdot \frac{t-1}{m-k} \\
\geq & ~ \frac{2}{3} t
\end{align*}
where the third step follows since $\frac{t- i}{m-(k+i-1)}$ is decreasing in $i$ and the last step follows from $k, t \ll m$. Now we can bound the tail probability by using concentration inequality of geometric distribution. We use Lemma~\ref{lem:geo_tail} by setting $\lambda = 2 + \frac{2}{t}\log\frac{1}{\delta}$ and have
\begin{align*}
\Pr\left\{X \geq (2 + \frac{2}{t}\log\frac{1}{\delta}) \mu\right\} \leq & ~  \exp(-p_*\mu(1+\frac{2}{t}\log\frac{1}{\delta}-\log(2 + \frac{2}{t}\log\frac{1}{\delta}))) \\
\leq & ~ \exp(-\frac{2t}{3}(1+\frac{2}{t}\log\frac{1}{\delta}-\log(2 + \frac{2}{t}\log\frac{1}{\delta})))
\end{align*}
In order to show that RHS is less than $\delta$, we only need to show $1+\frac{2}{t}\log\frac{1}{\delta}-\log(2 + \frac{2}{t}\log\frac{1}{\delta}) \geq \frac{3}{2t} \log\frac{1}{\delta}$. We define $f(x) = 1 + \frac{x}{2} - \log(2+2x)$, then we know $f(x)$ is decreasing for $0 \leq x \leq 1$ and increasing for $x >1$, thus $f_{\min} = f(1) = \frac{3}{2} - \log 4 > 0$. Since $\frac{1}{t} \log\frac{1}{\delta} > 0$ we have $f(\frac{1}{t} \log\frac{1}{\delta}) > 0$, which gives
\begin{align*}
\Pr\left\{X \geq (2 + \frac{2}{t}\log\frac{1}{\delta}) \mu\right\} \leq \delta.
\end{align*}
This shows that with probability at least $1-\delta$, the number of calls to the oracle is at most
\begin{align*}
X \leq (2 + \frac{2}{t}\log\frac{1}{\delta})\cdot t \cdot \left(1+\frac{2k+t-1}{m}\right) \leq 4t + 4 \log\frac{1}{\delta}
\end{align*}
which is $O(t+\log\frac{1}{\delta})$.
\end{proof}

\begin{lemma}[Approximately isotropic $k$-DPP]
\label{lem:approx_iso_fixed}
Given matrix $\A\in\R^{m\times n}$, denote $\mathbf{Q} = \frac{1}{\sqrt{m}}\H \mathbf{D}$ as the RHT matrix and $\bar{\A} = \Q\A$ as the preprocessed matrix. Let $S_{\dpp}\sim k$-$\dpp(\bar{\A}\bar{\A}^\top)$, for any $0 < \delta < 1$, with probability $1-\delta$ we have
\begin{align*}
\Pr\{j \in S_{\dpp}\} \leq \left(\sqrt{\frac{k}{m}} + \sqrt{\frac{8\log(m / \delta)}{m}}\right)^2 ~~~\text{for all}~~~ j \in [m].
\end{align*}
\end{lemma}
\begin{proof}
Although there is no explicit expression for the marginals of general fixed size DPP, there is one specific class of fixed size DPP called Projection DPP which has simple expressions for the marginals. Moreover, sampling a $k$-$\dpp$ is equivalent to sampling a mixture of Projection DPPs, see Lemma~\ref{lem:sample_dpp_projection}. Let $\A = \U\mathbf{\Sigma}\V^\top$ be the SVD of $\A$ and denote $\bar{\U} = \Q\U$, then we have eigendecomposition $\bar{\A}\bar{\A}^\top = \bar{\U}(\mathbf{\Sigma}\mathbf{\Sigma}^\top)\bar{\U}^\top$. Denote $r = \rank(\bar{\A}\bar{\A}^\top) = \rank(\A)$. Lemma~\ref{lem:sample_dpp_projection} shows that if we first sample $\gamma = (\gamma_1, \ldots, \gamma_r)$ where $\gamma_i\sim\mathrm{Bernoulli}(\frac{\lambda_i}{\lambda_i +1})$ are independent, and then sample $S_\gamma \sim \mathrm{P}$-$\dpp(\bar{\U}_{:,\gamma}\bar{\U}_{:,\gamma}^\top)$, where $\bar{\U}_{:,\gamma}$ is the submatrix of columns of $\bar{\U}$ indexed by the non-zeros in $\gamma$, then conditioned on the event that $\sum_{i} \gamma_i = k$, $S_\gamma$ is distributed the same as $S_{\dpp}\sim k$-$\dpp(\bar{\A}\bar{\A}^\top)$.

The advantage of decomposing $k$-DPP into $\mathrm{P}$-DPPs is that we can explicitly express marginals of $\mathrm{P}$-DPP. Since $\bar{\U}_{:,\gamma}\bar{\U}_{:,\gamma}^\top = \bar{\U}_{:,\gamma}\bar{\U}_{:,\gamma}^\dagger$ is a projection matrix,  we know that the marginals of $\mathrm{P}$-$\dpp(\bar{\U}_{:,\gamma}\bar{\U}_{:,\gamma}^\top)$ can be expressed as the diagonal entries of this kernel matrix as (e.g., see \cite{dm21})
\begin{align*}
\Pr\{j \in S_\gamma\} = (\bar{\U}_{:,\gamma}\bar{\U}_{:,\gamma}^\top)_{j,j} = \|\e_j^\top \bar{\U}_{:,\gamma}\|^2 ~~~\text{where}~~~ j\in[m].
\end{align*}
Based on this result, we can compute the marginals of $S_{\dpp}$ by summing over the marginals of all possible P-DPPs. For $j\in[m]$ we have
\begin{align*}
\Pr\{j \in S_{\dpp}\} = \sum_{\gamma \in \{0,1\}^r} \left(\Pr\{j \in S_\gamma\}\cdot\Pr\{\gamma \mid \sum_i \gamma_i = k\} \right) = \sum_{\gamma \in \{0,1\}^r} \left(\|\e_j^\top \bar{\U}_{:,\gamma}\|^2\cdot\Pr\{\gamma \mid \sum_i \gamma_i = k\} \right).
\end{align*}
Note that by definition we have
\begin{align*}
\|\e_j^\top \bar{\U}_{:,\gamma}\|^2 = \|\e_j^\top \Q\U_{:,\gamma}\|^2 = \frac{1}{m}\|\e_j^\top\H\mathbf{D}\U_{:,\gamma}\|^2 = \frac{1}{m}\|\mathbf{d}^\top \diag(\e_j^\top\H)\U_{:,\gamma}\|^2,
\end{align*}
where $\mathbf{d}$ is the vector of Rademacher variables along the diagonal of $\D$. If we denote $\mathbf{E}_j := \diag(\e_j^\top\H)$ and $p_{\gamma} := \Pr\{\gamma \mid \sum_i \gamma_i = k\}$, then we have
\begin{align*}
\Pr\{j \in S_{\dpp}\} = & ~ \sum_{\gamma \in \{0,1\}^r} p_{\gamma}\cdot \|\e_j^\top \bar{\U}_{:,\gamma}\|^2 \\
= & ~ \frac{1}{m} \sum_{\gamma \in \{0,1\}^r} p_{\gamma}\cdot \|\mathbf{d}^\top \mathbf{E}_j\U_{:,\gamma}\|^2. \\ 
= & ~ \frac{1}{m} \sum_{\gamma \in \{0,1\}^r} p_{\gamma}\cdot \mathbf{d}^\top\mathbf{E}_j\U_{:,\gamma}\U_{:,\gamma}^\top \mathbf{E}_j \mathbf{d} \\ 
= & ~ \frac{1}{m} \mathbf{d}^\top \left(\sum_{\gamma \in \{0,1\}^r} p_{\gamma} \mathbf{E}_j \U_{:,\gamma}\U_{:,\gamma}^\top\mathbf{E}_j\right)\mathbf{d}.
\end{align*}
We define function $f_j(\x) = \sqrt{\frac{1}{m} \x^\top\B_j \x}$ where $\B_j := \sum_{\gamma \in \{0,1\}^r} p_{\gamma} \mathbf{E}_j \U_{:,\gamma}\U_{:,\gamma}^\top\mathbf{E}_j$. We first analyze the properties of $\B_j$. Since $\mathbf{E}_j^2 = \I$ and $\U_{:,\gamma}^\top\U_{:,\gamma} = \I$, we have
\begin{align*}
\|\B_j\| \leq \sum_{\gamma \in \{0,1\}^r} p_{\gamma} \cdot\|\mathbf{E}_j \U_{:,\gamma}\U_{:,\gamma}^\top\mathbf{E}_j\| \leq \sum_{\gamma \in \{0,1\}^r} p_{\gamma} \cdot\| \U_{:,\gamma}\U_{:,\gamma}^\top\| = 1
\end{align*}
and
\begin{align*}
\tr(\B_j) = \sum_{\gamma \in \{0,1\}^r} p_{\gamma}\cdot \tr(\mathbf{E}_j \U_{:,\gamma}\U_{:,\gamma}^\top\mathbf{E}_j) = \sum_{\gamma \in \{0,1\}^r} p_{\gamma} \cdot \tr(\U_{:,\gamma}^\top\U_{:,\gamma}) = k\cdot\left(\sum_{\gamma \in \{0,1\}^r} p_{\gamma}\right) = k.
\end{align*}
Next we analyze the properties of $f_j$. Note that $f_j$ is convex, with Lipschitz constant as follows:
\begin{align*}
|f_j(\x) - f_j(\y)| = \frac{1}{\sqrt{m}}|\|\x\|_{\B_j} - \|\y\|_{\B_j}| \leq \frac{1}{\sqrt{m}} \|\x-\y\|_{\B_j} \leq \frac{1}{\sqrt{m}} \|\B_j\|\cdot \|\x-\y\| \leq \frac{1}{\sqrt{m}} \|\x-\y\|.
\end{align*}
We consider the random variable $f_j(\mathbf{d})$ and bound the expectation as follows:
\begin{align*}
\E[f_j(\mathbf{d})] \leq (\E[f_j(\mathbf{d})^2])^{1/2} = \left(\frac{1}{m} \E[\mathbf{d}^\top\B_j \mathbf{d}]\right)^{1/2} = \left(\frac{1}{m} \tr(\B_j)\right)^{1/2} = \sqrt{\frac{k}{m}}.
\end{align*}
Then we use Lemma~\ref{lem:rademacher} on the concentration of a Lipschitz function of a Rademacher random vector, with $t = \sqrt{8\log(m / \delta)}$, and obtain
\begin{align*}
\Pr\left\{\sqrt{\frac{1}{m} \mathbf{d}^\top\B_j \mathbf{d}} \geq \sqrt{\frac{k}{m}} + \sqrt{\frac{8\log(m/ \delta)}{m}} \right\} \leq \frac{\delta}{m}.
\end{align*}
Further notice that $\Pr\{j \in S_{\dpp}\} = f_j^2(\mathbf{d})= \frac{1}{m} \mathbf{d}^\top\B_j \mathbf{d}$, thus by applying union bound we have that with probability $1-\delta$,
\begin{align*}
\Pr\{j \in S_{\dpp}\} \leq \left(\sqrt{\frac{k}{m}} + \sqrt{\frac{8\log(m / \delta)}{m}}\right)^2 ~~~\text{for all}~~~ j \in [m].
\end{align*}
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
According to Lemma~\ref{lem:approx_iso_fixed} and Remark~\ref{rem:approx_iso}, with probability $0.99$ we have $\Pr\{j \in S_{\dpp}\} \leq \frac{c_0 k}{m}$ holds for all $j\in[m]$ for some constant $c_0 = O(1)$, which gives
\begin{align*}
K := \sum_{j=1}^m \Pr\{j \in S_{\dpp}\} \leq c_0 k.
\end{align*}
By combining this result with Lemma~\ref{lem:anari_main_2}, we know that conditioned on an event that holds with probability $0.99$, Algorithm~\ref{alg:dpp_sample_ghost} produces a sample from a distribution with total variation distance $m^{-O(1)}$ from the $k$-DPP distribution with $O(\log^3 m)$ iterations of up-down walk, and size of the super set needs to satisfies $|T_i| = O(K)$. Since we know that $K = O(k)$, the constraints become $|T_i| = O(k)$ for all $i$. By Lemma~\ref{lem:sample_log}, in order to satisfy $|T_i| = t-k = O(k)$ for all $i$
holds with probability $1 - \frac{\delta}{2}$, we need to set
\begin{align*}
\mathrm{call} = O(t-k + \log\frac{2\mathrm{iter}}{\delta}) = O(k+ \log\log m + \log\frac{1}{\delta}) = O(k+\log\frac{1}{\delta}).
\end{align*}
We set $\delta = m^{-O(1)}$ and have $\log \frac{1}{\delta} = O(\log m)$, thus there exists a constant $C=O(1)$ such that it suffices to set $\mathrm{call} \geq Ck$. Then we can apply a union bound and know that with probability $1-\frac{\delta}{2}$, we can obtain all $\{T_i\}_{i=1}^{\mathrm{iter}}$ such that $|T_i| = t-k$ and $T_i \cap S_{i-1} = \varnothing$. Finally, by using Lemma~\ref{lem:tv_distance} and applying another union bound again, we know that $\Pr\{S_{\mathrm{iter}} = S_{\dpp}\} = 1 - \delta$.
\end{proof}
